"""One explicit, keyed proposal. Does not write regional scientific inputs."""
from pathlib import Path
import json, hashlib, math, collections, csv, re

ROOT = Path.cwd()
MODEL = ROOT/'regions/LME/LME_022/papers/ICES-WGSAM-2015/models/ICES_WGSAM2015_North_Sea_1991'
RUN = MODEL/'model_validation/work/2026-11-14_200000_ices_full_review'
OUT = MODEL/'model_validation/evidence/mapping'
OUT.mkdir(parents=True, exist_ok=True)
data = json.loads((RUN/'inputs/mapping_inputs.json').read_text(encoding='utf8'))
catch = [r for r in data['catch'] if r['catch_basis']=='catch']
assert len(catch)==384 and len({r['taxon'] for r in catch})==384
classic = {r['taxon']:r for r in data['classic']}
groups = {int(g['group_seq']):g for g in data['model']['group']}
exploited = json.loads((ROOT/'regions/LME/LME_022/raw/catch/LME_022-exploited.json').read_text(encoding='utf8'))
exploited = {r['scientific_name']:r for r in exploited['data']}
decisions = {}

def assign(indices, ids, rule, confidence, rationale, locator, sources=None, uncertainty=None):
    if isinstance(indices,str):
        inds=[]
        for tok in indices.split(','):
            if '-' in tok:
                a,b=map(int,tok.split('-'));inds.extend(range(a,b+1))
            elif tok.strip():inds.append(int(tok))
    else: inds=indices
    if isinstance(ids,int):ids=[ids]
    for i in inds:
        assert i not in decisions, (i,catch[i]['taxon'])
        decisions[i]={'taxon':catch[i]['taxon'],'candidate_group_ids':ids,
            'membership_rule':rule,'membership_confidence':confidence,
            'membership_rationale':rationale,'membership_locator':locator,
            'membership_sources':sources or ['ICES2015','CEFAS2007','SAU'],
            'very_low_reason':uncertainty if confidence=='Very low' else None}

