# Final source reconciliation. Dedicated biological definitions take precedence where
# they conflict with historical catch-accounting shortcuts; all conflicts stay explicit.
def revise(indices, ids, rule, confidence, rationale, locator, uncertainty=None):
    for i in indices:
        decisions[i].update(candidate_group_ids=ids,membership_rule=rule,membership_confidence=confidence,membership_rationale=rationale,membership_locator=locator,very_low_reason=uncertainty if confidence=='Very low' else None)
