missing=[(i,r['taxon']) for i,r in enumerate(catch) if i not in decisions]
if missing: raise RuntimeError(f'Explicit decisions missing: {missing}')

levels=['High','Medium','Low','Very low','Unresolved']
rows=[]
for i,c in enumerate(catch):
    d=decisions[i]
    candidates=[]
    for gid in d['candidate_group_ids']:
        g=groups[gid]
        def number(x):
            try:v=float(x)
            except (TypeError,ValueError):return None
            return v if math.isfinite(v) and v>=0 else None
        candidates.append({'group_id':gid,'group_name':g['group_name'],
          'source_landings_t_km2_year':number(g.get('landings_total')),
          'source_discards_t_km2_year':number(g.get('discards_total')),
          'source_catch_t_km2_year':number(g.get('total_removals')),
          'source_biomass_t_km2':number(g.get('biomass'))})
    if len(candidates)==1:
        arule,aconf,weights='W1','High',[1.0]
        arationale='No split: all catch assigned to the one proposed group.'
        rejected=None
    else:
        values=[x['source_catch_t_km2_year'] for x in candidates]
        rejected=None
        if all(x is not None for x in values) and sum(values)>0:
            arule,aconf='W4','Medium';weights=[v/sum(values) for v in values]
            arationale='Exact 1991 Rpath total removals (all 11 fleets, landings plus discards) divided by the eligible-set sum; assumed representative of 2019 LME catch composition. Genuine zero candidates retained.'
        else:
            rejected={'values':values,'reason':'missing/invalid source catch or nonpositive complete total'}
            values=[x['source_biomass_t_km2'] for x in candidates]
            if all(x is not None for x in values) and sum(values)>0:
                arule,aconf='W9','Medium';weights=[v/sum(values) for v in values]
                arationale='Source catch proportions unavailable. Exact 1991 Rpath group biomass divided by eligible-set total, assuming equal relative catchability and transfer to 2019.'
            else:raise RuntimeError(('No justified allocation',d['taxon'],candidates))
    for a,w in zip(candidates,weights):a['weight']=w
    cl=classic.get(c['taxon'],{})
    cv=c.get('2019');sppr=cl.get('sppr')
    ppr=0.0 if cv==0 else cv*sppr/9 if cv is not None and sppr is not None else None
    overall=max((d['membership_confidence'],aconf),key=levels.index)
    reason=d['membership_rationale']+' '+('No allocation split.' if arule=='W1' else 'Weights: 1991 model total-catch proportions, assumed transferable to 2019.' if arule=='W4' else 'Weights: 1991 biomass proxy after unusable model catch.')+' ['+', '.join(d['membership_sources'])+']'
    rows.append({**d,'model_id':'ICES_WGSAM2015_North_Sea_1991','unit_id':'LME_022',
      'proposal_status':'proposed_not_adopted','prior_mapping':None,'stored_prior_confidence':None,
      'catch_basis':'catch','year':2019,'catch_tonnes':cv,'tl':cl.get('tl'),'classic_sppr':sppr,
      'simple_chain_ppr_tC':ppr,'missing_coefficient':sppr is None,'missing_tl':cl.get('tl') is None,
      'catch_common_name':c.get('common_name'),'catch_functional_group':c.get('functional_group'),
      'catch_commercial_group':c.get('commercial_group'),'source_unidentified':c.get('unidentified'),
      'provider_taxon_metadata':exploited.get(c['taxon']),
      'groups':candidates,'allocation_rule':arule,'allocation_confidence':aconf,
      'allocation_rationale':arationale,'allocation_source':'model.json group.total_removals (sum landings_total + discards_total); native Rpath_parameter_model.csv all 11 fleet landings/discards',
      'allocation_rejected_catch':rejected,'overall_confidence':overall,'reason':reason,
      'unresolved_reason':None,'assumptions':{'membership_inferred':d['membership_confidence']!='High','allocation_assumed':arule!='W1','target_period':2019,'source_period':1991,'source_model_domain':'North Sea ICES IVa–c','target_domain':'LME_022','fixed_across_years_not_verified':True}})
rows.sort(key=lambda r:(r['simple_chain_ppr_tC'] is None,-(r['simple_chain_ppr_tC'] or 0),r['taxon']))
totalcatch=sum(r['catch_tonnes'] for r in rows if r['catch_tonnes'] is not None)
totalppr=sum(r['simple_chain_ppr_tC'] for r in rows if r['simple_chain_ppr_tC'] is not None)
summary=[]
for lev in levels:
    rr=[r for r in rows if r['overall_confidence']==lev]
    cs=sum(r['catch_tonnes'] or 0 for r in rr);ps=sum(r['simple_chain_ppr_tC'] or 0 for r in rr)
    summary.append({'confidence':lev,'taxa':len(rr),'catch_tonnes':cs,'simple_chain_ppr_tC':ps,'catch_percent':100*cs/totalcatch,'ppr_percent':100*ps/totalppr})
rule_names={'M1':'Taxon explicitly included in focal model documentation','M3':'Unambiguous fit to a named focal stock or taxonomic group','M4':'Taxonomic extension from listed representatives','M5':'Supported ecological extension of a residual group','M6':'Conflicting source placements resolved with stated uncertainty','M9':'Inferred eligible group set from regional taxonomy and source definitions','M10':'Broad reporting category approximated by compatible named and residual groups','M11':'Closest represented taxonomic or ecological analogue','M12':'Compatible membership transferred from the documented predecessor','W1':'One group; no allocation split','W4':'Historical model total-catch proportions transferred to the catch-year mixture','W9':'Historical model biomass proportions after unusable source catch'}
def rules(component):
    grouped=collections.defaultdict(list)
    for r in rows:grouped[(r[component+'_rule'],r[component+'_confidence'])].append(r)
    result=[]
    for (rule,conf),rr in grouped.items():
        result.append({'rule':rule,'plain_language_rule':rule_names[rule],'confidence':conf,'taxa':len(rr),'ppr_percent':100*sum(r['simple_chain_ppr_tC'] or 0 for r in rr)/totalppr})
    return sorted(result,key=lambda r:-r['ppr_percent'])
verylow=collections.defaultdict(list)
for r in rows:
    if r['overall_confidence']=='Very low':verylow[r['very_low_reason']].append(r['taxon'])
assert None not in verylow
