payload={'schema_version':1,'status':'complete_local_mapping_proposal_pending_researcher_review_and_adoption','unit_id':'LME_022','model_id':'ICES_WGSAM2015_North_Sea_1991','year':2019,'catch_basis':'catch','catch_basis_definition':'landings plus discards','source_group_count':69,'taxon_count':384,'input_sha256':identity,'input_table_hashes':{k:hashlib.sha256(json.dumps(data[k],sort_keys=True,ensure_ascii=False).encode()).hexdigest() for k in ['catch','classic','matching']},'totals':{'catch_tonnes':totalcatch,'simple_chain_ppr_tC':totalppr,'missing_coefficients':sum(r['missing_coefficient'] for r in rows),'unknown_annual_contributions':sum(r['simple_chain_ppr_tC'] is None for r in rows)},'confidence_counts_shares':summary,'membership_rule_summaries':rules('membership'),'allocation_rule_summaries':rules('allocation'),'very_low_decisions':[{'taxa':sorted(names),'reason':reason} for reason,names in verylow.items()],'unresolved':[],'sources':sources,'rows':rows}
