(RUN/'outputs/report_handoff.json').write_text(json.dumps(handoff,ensure_ascii=False,indent=2),encoding='utf8')
print(json.dumps({'taxa':len(rows),'catch_tonnes':totalcatch,'simple_chain_ppr_tC':totalppr,'summary':summary,'missing':missing},indent=2))
